tool_input.command:
$h=@{'User-Agent'='dsh-agent'}
foreach ($u in @('https://api.github.com/users/Fish-under-sea','https://api.github.com/repos/Fish-under-sea/dsh-our-free-model-fish','https://api.github.com/repos/Fish-under-sea/dsh-fish','https://api.github.com/repos/Fish-under-sea/dsh-our-free-model-fish/forks')) {
  Write-Output "=== $u ==="
  try { $j = Invoke-RestMethod -Uri $u -Headers $h -TimeoutSec 25
    if ($j.PSObject.Properties.Name -contains 'login') { $j | Select-Object login,type,name,bio,company,blog,location,public_repos,followers,created_at | Format-List | Out-String -Width 160 }
    elseif ($j -is [array]) { $j | Select-Object -First 5 full_name,description,stargazers_count,pushed_at | Format-Table -AutoSize | Out-String -Width 200 }
    else { $j | Select-Object full_name,description,homepage,language,size,stargazers_count,forks_count,open_issues_count,created_at,pushed_at,updated_at,license,default_branch,fork,parent,topics | Format-List | Out-String -Width 160 }
  } catch { Write-Output "FAILED: $($_.Exception.Message)" }
}
